/* QMES inventory screen rebuilt independently of legacy stock views. */
(()=>{'use strict';
const root=document.getElementById('inventory');if(!root)return;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const category={RM:'원자재',WIP:'중간배치',FG:'완제품',PM:'부자재'},status={AVAILABLE:'사용가능',IQC_PENDING:'IQC 대기',OQC_PENDING:'OQC 대기',HOLD:'보류',NONCONFORM:'부적합',RESERVED:'예약'};
let records=[],filtered=[],page=1,cat='',collapsed=false;
root.innerHTML=`<div class="namo-new-stock qmes-stock-rebuilt"><header><div><h1>재고현황 등록 및 조회</h1></div><div><button id="stockCsv" type="button">엑셀 내보내기</button></div></header><nav class="namo-stock-tabs"><button data-cat="" class="active">전체</button><button data-cat="RM">원자재</button><button data-cat="WIP">중간배치</button><button data-cat="FG">완제품</button><button data-cat="PM">부자재</button></nav><section class="stockFilters"><label>재고 구분 <select id="stockCat"><option value="">전체</option>${Object.entries(category).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>품질상태 <select id="stockStatus"><option value="">전체</option>${Object.entries(status).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>보관위치 <input id="stockLocation" placeholder="전체"></label><label>품목·LOT 검색 <input id="stockSearch" placeholder="품목코드·품목명·LOT NO"></label></section><div class="stock-select-toolbar" id="stockSelection" hidden><button data-action="print">선택 인쇄 (0)</button><button data-action="mail">선택 메일 발송 (0)</button><button data-action="delete">선택 삭제 (0)</button></div><div class="stock-wo-tools"><strong>▸ 재고현황 <span id="stockCount"></span></strong><div><button id="stockClear">조건 지우기</button><button id="stockSearchButton" title="조회" aria-label="조회">⌕</button><button id="stockFold" title="접기" aria-label="접기">⌃</button></div></div><div class="stockTable" id="stockTable"><table><thead><tr><th><input type="checkbox" id="stockAll"></th><th>No.</th><th>구분</th><th>품목코드</th><th>품목명</th><th>LOT NO</th><th>기초재고</th><th>입고</th><th>출고</th><th>기말재고(kg)</th><th>가용재고(kg)</th><th>상태</th><th>보관위치</th><th>비고</th></tr></thead><tbody id="stockRows"></tbody></table></div><nav id="stockPager"></nav><p id="stockError" role="status" hidden></p><button id="stockReload" hidden>새로고침</button><button id="stockPrint" hidden>인쇄</button></div>`;
const $=s=>root.querySelector(s),fmt=n=>(Number(n)||0).toLocaleString('ko-KR',{minimumFractionDigits:3,maximumFractionDigits:3});
function selection(){const n=root.querySelectorAll('.stock-row-check:checked').length;$('#stockSelection').hidden=!n;root.querySelectorAll('#stockSelection [data-action]').forEach(b=>b.textContent=({print:'선택 인쇄',mail:'선택 메일 발송',delete:'선택 삭제'})[b.dataset.action]+' ('+n+')');}
function draw(){const list=filtered.slice((page-1)*10,page*10);$('#stockCount').textContent='('+filtered.length+'건)';$('#stockRows').innerHTML=list.map((r,i)=>`<tr><td><input class="stock-row-check" type="checkbox" data-key="${esc([r.item_code,r.lot_no,r.location_code,r.quality_status].join('|'))}"></td><td>${(page-1)*10+i+1}</td><td>${esc(category[r.category]||r.category)}</td><td>${esc(r.item_code)}</td><td>${esc(r.item_name)}</td><td><span class="stockLot">${esc(r.lot_no)}</span></td><td>—</td><td>—</td><td>—</td><td>${fmt(r.quantity)}</td><td>${fmt(r.available_qty)}</td><td>${esc(status[r.quality_status]||r.quality_status)}</td><td>${esc(r.location_code)}</td><td><button class="stockPrintRow" type="button">인쇄</button> <button class="stockEditRow" type="button">수정</button> <button class="stockDeleteRow" type="button">삭제</button></td></tr>`).join('')||'<tr><td colspan="14">조회 결과가 없습니다.</td></tr>';$('#stockAll').checked=false;$('#stockSelection').hidden=true;const max=Math.max(1,Math.ceil(filtered.length/10));$('#stockPager').innerHTML='<button data-page="prev" '+(page===1?'disabled':'')+'>‹</button>'+Array.from({length:max},(_,i)=>'<button data-page="'+(i+1)+'" '+(i+1===page?'class="active"':'')+'>'+(i+1)+'</button>').join('')+'<button data-page="next" '+(page===max?'disabled':'')+'>›</button>';}
function filter(){const q=$('#stockSearch').value.toLowerCase().trim(),loc=$('#stockLocation').value.toLowerCase().trim(),kind=$('#stockCat').value,st=$('#stockStatus').value;filtered=records.filter(r=>(!kind||r.category===kind)&&(!st||r.quality_status===st)&&(!loc||String(r.location_code||'').toLowerCase().includes(loc))&&(!q||[r.item_code,r.item_name,r.lot_no].join(' ').toLowerCase().includes(q)));page=1;draw();}
async function load(){try{const res=await fetch('/api/inventory/stock',{credentials:'same-origin',cache:'no-store'});const json=await res.json();if(!res.ok||json.success===false)throw Error(json.message||'조회 실패');records=json.data||json;if(!Array.isArray(records))throw Error('데이터 형식 오류');$('#stockError').hidden=true;filter();}catch(e){$('#stockError').hidden=false;$('#stockError').textContent='재고 조회 오류: '+e.message;}}
root.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));$('#stockCat').value=b.dataset.cat;filter();});
['stockCat','stockStatus','stockLocation','stockSearch'].forEach(id=>{$('#'+id).addEventListener(id==='stockCat'||id==='stockStatus'?'change':'input',filter);});
$('#stockClear').onclick=()=>{$('#stockCat').value='';$('#stockStatus').value='';$('#stockLocation').value='';$('#stockSearch').value='';root.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',!b.dataset.cat));filter();};
$('#stockSearchButton').onclick=()=>{collapsed=false;$('#stockTable').hidden=false;$('#stockPager').hidden=false;$('#stockFold').textContent='⌃';load();};
$('#stockFold').onclick=()=>{collapsed=!collapsed;$('#stockTable').hidden=collapsed;$('#stockPager').hidden=collapsed;$('#stockFold').textContent=collapsed?'⌄':'⌃';};
$('#stockReload').onclick=load;
$('#stockPager').onclick=e=>{const v=e.target.closest('[data-page]')?.dataset.page;if(!v)return;page=v==='prev'?Math.max(1,page-1):v==='next'?Math.min(Math.ceil(filtered.length/10)||1,page+1):Number(v);draw();};
$('#stockRows').addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;const tr=btn.closest('tr'),i=[...$('#stockRows').children].indexOf(tr),row=filtered[(page-1)*10+i];if(!row)return;if(btn.classList.contains('stockPrintRow')){const w=window.open('','_blank');if(!w)return;w.document.write('<!doctype html><html lang="ko"><meta charset="utf-8"><title>재고현황</title><body><h2>재고현황</h2><p>'+esc(row.item_name)+' / '+esc(row.lot_no)+'</p><p>현재고(kg): '+fmt(row.quantity)+'</p></body></html>');w.document.close();w.print();}else if(btn.classList.contains('stockEditRow')){alert('재고 수정은 수량 조정 이력을 남기는 관리자 기능과 연결한 후 사용할 수 있습니다.');}else if(btn.classList.contains('stockDeleteRow')){alert('데이터 보호를 위해 개별 재고 삭제 기능은 아직 연결되지 않았습니다.');}});
$('#stockAll').onchange=e=>{root.querySelectorAll('.stock-row-check').forEach(b=>b.checked=e.target.checked);selection();};$('#stockRows').onchange=selection;
$('#stockSelection').onclick=e=>{const a=e.target.dataset.action;if(!a)return;if(a==='delete'){alert('재고 원장 데이터 삭제는 관리자 검증 기능이 필요합니다. 선택된 데이터는 변경되지 않았습니다.');return;}if(a==='mail'){location.href='mailto:?subject='+encodeURIComponent('QMES 재고현황')+'&body='+encodeURIComponent([...root.querySelectorAll('.stock-row-check:checked')].map(x=>x.dataset.key).join('\n'));return;}const w=window.open('','_blank');if(!w)return;w.document.write('<html><head><meta charset="utf-8"></head><body><h2>재고 선택 인쇄</h2><pre>'+esc([...root.querySelectorAll('.stock-row-check:checked')].map(x=>x.dataset.key).join('\n'))+'</pre></body></html>');w.document.close();w.print();};
$('#stockCsv').onclick=()=>{const rows=[['구분','품목코드','품목명','LOT NO','기말재고(kg)','가용재고(kg)','상태','보관위치'],...filtered.map(r=>[category[r.category],r.item_code,r.item_name,r.lot_no,r.quantity,r.available_qty,status[r.quality_status],r.location_code])];const data='\uFEFF'+rows.map(a=>a.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='QMES_재고현황.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
const style=document.createElement('style');style.textContent=`#inventory .qmes-stock-rebuilt{background:white;border:1px solid #d5e1ef;border-radius:9px;overflow:hidden;color:#27445e}#inventory .qmes-stock-rebuilt header{display:flex;justify-content:space-between;align-items:center;padding:15px;border-bottom:1px solid #dae4ee}#inventory .qmes-stock-rebuilt h1{font-size:17px;margin:0;padding-left:10px;border-left:3px solid #1975bf}#inventory .qmes-stock-rebuilt button{padding:7px 11px;border:1px solid #cad9e8;border-radius:5px;background:white;color:#245078;cursor:pointer;font-size:11px}#inventory .namo-stock-tabs{display:flex;gap:18px;padding:8px 16px;border-bottom:1px solid #e1e9f3}#inventory .namo-stock-tabs button{border:0;border-radius:0}#inventory .namo-stock-tabs button.active{border-bottom:2px solid #267fda;color:#166bb8;font-weight:bold}#inventory .stockFilters{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 16px;background:#f2f6fb}#inventory .stockFilters label{display:flex;align-items:center;gap:7px;font-size:11px}#inventory .stockFilters input,#inventory .stockFilters select{height:30px;border:1px solid #cddbea;border-radius:4px;padding:4px 8px;background:white}#inventory .stock-wo-tools{display:flex;justify-content:space-between;align-items:center;padding:12px 15px}#inventory .stock-wo-tools strong{font-size:12px}#inventory .stock-wo-tools>div{display:flex;gap:7px}#inventory .stockTable{padding:0 12px;overflow:auto}#inventory .stockTable table{border-collapse:collapse;width:100%;font-size:11px;white-space:nowrap}#inventory .stockTable th,#inventory .stockTable td{border:1px solid #d9e4ef;padding:10px;text-align:center}#inventory .stockTable th{background:#e8f1f9;color:#264d6e}#inventory .stockPrintRow{background:#e7f2ff!important;color:#0b67ad!important}#inventory .stockDeleteRow{background:#fff6f5!important;color:#b2352c!important;border-color:#f0cbc8!important}#inventory .stockLot{color:#0d70c4;text-decoration:underline}#inventory #stockPager{text-align:center;padding:18px;display:flex;gap:5px;justify-content:center}#inventory #stockPager button.active{background:#297cda;color:white}#inventory .stock-select-toolbar{display:flex;justify-content:flex-end;gap:8px;padding:9px 14px;background:#f2f6fb}#inventory .stock-select-toolbar[hidden]{display:none}#inventory #stockError{padding:10px;color:#b12b2b}`;document.head.append(style);load();
})();